import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import * as lex from "./index.ts";

// Vectors are generated by ts/tools/gen-lex-vectors from Go's real lex package.
// Byte slices are lowercase hex, "" is an empty slice, and null is a Go nil
// slice. Where the TypeScript result cannot be nil (every result except
// TrimLeft's whitespaces and TrimWhitespace), a Go nil is accepted as an empty
// array; see the PORT-NOTE comments in token.ts.

interface GoCase {
  args: unknown[];
  ret: unknown;
  panic: boolean;
  after?: string;
}

interface LexerCase {
  input: string;
  lines: (string | null)[];
  inputAfter: string;
}

interface Vectors {
  goVersion: string;
  unicodeVersion: string;
  functions: Record<string, GoCase[]>;
  lexer: LexerCase[];
}

const vectors: Vectors = JSON.parse(readFileSync(new URL("./testdata/lex_vectors.json", import.meta.url), "utf8"));

// fromHex decodes a hex string into a fresh array whose capacity equals its length.
const fromHex = (s: string): Uint8Array => new Uint8Array(Buffer.from(s, "hex"));

// hx encodes a byte slice as hex, and null (Go nil) as null.
const hx = (u: Uint8Array | null): string | null => (u === null ? null : Buffer.from(u).toString("hex"));

const hxs = (xs: Uint8Array[]): string[] => xs.map((x) => hx(x) as string);

interface Result {
  ret: unknown;
  after?: string;
}

// calls maps each lex function to a call on the vector arguments. Each call builds
// its own input buffers, so in-place calls do not share state.
const calls: Record<string, (a: any[]) => Result> = {
  IsWhitespace: (a) => ({ ret: lex.IsWhitespace(a[0]) }),
  IsUnicodeWhitespace: (a) => ({ ret: lex.IsUnicodeWhitespace(a[0]) }),
  IsDigit: (a) => ({ ret: lex.IsDigit(a[0]) }),
  IsHexDigit: (a) => ({ ret: lex.IsHexDigit(a[0]) }),
  TokenToUpper: (a) => ({ ret: lex.TokenToUpper(a[0]) }),
  IsASCIIPunct: (a) => ({ ret: lex.IsASCIIPunct(a[0]) }),
  IsASCIILetter: (a) => ({ ret: lex.IsASCIILetter(a[0]) }),
  IsASCIILetterNum: (a) => ({ ret: lex.IsASCIILetterNum(a[0]) }),
  IsASCIILetterNums: (a) => ({ ret: lex.IsASCIILetterNums(fromHex(a[0])) }),
  IsASCIILetterNumHyphen: (a) => ({ ret: lex.IsASCIILetterNumHyphen(a[0]) }),
  IsControl: (a) => ({ ret: lex.IsControl(a[0]) }),
  IsBlank: (a) => ({ ret: lex.IsBlank(fromHex(a[0])) }),
  Split: (a) => ({ ret: hxs(lex.Split(fromHex(a[0]), a[1])) }),
  SplitWithoutBackslashEscape: (a) => ({ ret: hxs(lex.SplitWithoutBackslashEscape(fromHex(a[0]), a[1])) }),
  ReplaceAll: (a) => {
    const buf = fromHex(a[0]);
    const r = lex.ReplaceAll(buf, a[1], a[2]);
    return { ret: hx(r), after: hx(buf) as string };
  },
  ReplaceNewlineSpace: (a) => ({ ret: hx(lex.ReplaceNewlineSpace(fromHex(a[0]))) }),
  TrimWhitespace: (a) => ({ ret: hx(lex.TrimWhitespace(fromHex(a[0]))) }),
  Trim: (a) => {
    const [l, r, rem] = lex.Trim(fromHex(a[0]));
    return { ret: [hx(l), hx(r), hx(rem)] };
  },
  TrimRight: (a) => {
    const [w, rem] = lex.TrimRight(fromHex(a[0]));
    return { ret: [hx(w), hx(rem)] };
  },
  TrimLeft: (a) => {
    const [w, rem] = lex.TrimLeft(fromHex(a[0]));
    return { ret: [hx(w), hx(rem)] };
  },
  Accept: (a) => ({ ret: lex.Accept(fromHex(a[0]), a[1]) }),
  AcceptTokenss: (a) => ({ ret: lex.AcceptTokenss(fromHex(a[0]), (a[1] as string[]).map(fromHex)) }),
  AcceptTokens: (a) => ({ ret: lex.AcceptTokens(fromHex(a[0]), fromHex(a[1])) }),
  IsBlankLine: (a) => ({ ret: lex.IsBlankLine(fromHex(a[0])) }),
  SplitWhitespace: (a) => ({ ret: hxs(lex.SplitWhitespace(fromHex(a[0]))) }),
  IsBackslashEscapePunct: (a) => ({ ret: lex.IsBackslashEscapePunct(fromHex(a[0]), a[1]) }),
  StatWhitespace: (a) => ({ ret: lex.StatWhitespace(fromHex(a[0])) }),
  Spnl: (a) => {
    const [ok, passed, remains] = lex.Spnl(fromHex(a[0]));
    return { ret: [ok, hx(passed), hx(remains)] };
  },
  Peek: (a) => ({ ret: lex.Peek(fromHex(a[0]), a[1]) }),
  BytesShowLength: (a) => ({ ret: lex.BytesShowLength(fromHex(a[0])) }),
  RepeatBackslashBeforePipe: (a) => ({ ret: lex.RepeatBackslashBeforePipe(a[0]) }),
  EscapeCommonMarkers: (a) => ({ ret: hx(lex.EscapeCommonMarkers(fromHex(a[0]))) }),
  EscapeProtyleMarkers: (a) => ({ ret: hx(lex.EscapeProtyleMarkers(fromHex(a[0]))) }),
  IsCommonInlineMarker: (a) => ({ ret: lex.IsCommonInlineMarker(a[0]) }),
  IsProtyleInlineMarker: (a) => ({ ret: lex.IsProtyleInlineMarker(a[0]) }),
  IsMarker: (a) => ({ ret: lex.IsMarker(a[0]) }),
};

// nilExact lists the functions whose nil results are represented as null.
const nilExact = new Set(["TrimLeft", "TrimWhitespace"]);

// check compares a got value with a vector value. A Go nil (null in the vector)
// must be null for nilExact functions, and may be an empty result otherwise.
function check(got: unknown, want: unknown, exact: boolean, where: string): void {
  if (want === null) {
    if (exact) {
      assert.equal(got, null, where);
    } else {
      assert.ok(got === null || got === "" || (Array.isArray(got) && got.length === 0), where);
    }
    return;
  }
  if (Array.isArray(want)) {
    assert.ok(Array.isArray(got), where);
    assert.equal(got.length, want.length, where);
    want.forEach((w, i) => check(got[i], w, exact, `${where}[${i}]`));
    return;
  }
  assert.deepEqual(got, want, where);
}

for (const [name, cases] of Object.entries(vectors.functions)) {
  test(`${name} matches Go (${cases.length} vectors)`, () => {
    const call = calls[name];
    assert.ok(call, `no TypeScript call for ${name}`);
    const exact = nilExact.has(name);
    cases.forEach((c, idx) => {
      const where = `${name}#${idx} args=${JSON.stringify(c.args)}`;
      if (c.panic) {
        assert.throws(() => call(c.args), where);
        return;
      }
      const got = call(c.args);
      check(got.ret, c.ret, exact, where);
      if (c.after !== undefined) {
        assert.equal(got.after, c.after, `${where} (input after the call)`);
      }
    });
  });
}

// GO_FUNCTIONS lists every exported function of lex/token.go (and NewLexer and
// NextLine in lex/lexer.go), so a missing port or vector shows up here.
const GO_FUNCTIONS = [
  "IsWhitespace", "IsUnicodeWhitespace", "IsDigit", "IsHexDigit", "TokenToUpper", "IsASCIIPunct",
  "IsASCIILetter", "IsASCIILetterNum", "IsASCIILetterNums", "IsASCIILetterNumHyphen", "IsControl",
  "IsBlank", "Split", "SplitWithoutBackslashEscape", "ReplaceAll", "ReplaceNewlineSpace",
  "TrimWhitespace", "Trim", "TrimRight", "TrimLeft", "Accept", "AcceptTokenss", "AcceptTokens",
  "IsBlankLine", "SplitWhitespace", "IsBackslashEscapePunct", "StatWhitespace", "Spnl", "Peek",
  "BytesShowLength", "RepeatBackslashBeforePipe", "EscapeCommonMarkers", "EscapeProtyleMarkers",
  "IsCommonInlineMarker", "IsProtyleInlineMarker", "IsMarker",
];

test("every exported function of token.go has a call and vectors", () => {
  assert.equal(GO_FUNCTIONS.length, 36);
  for (const name of GO_FUNCTIONS) {
    assert.equal(typeof (lex as unknown as Record<string, unknown>)[name], "function", name);
    assert.ok(calls[name], `call for ${name}`);
    assert.ok(vectors.functions[name]?.length > 0, `vectors for ${name}`);
  }
});

// The token constants are checked against the Go character literals.
test("token constants match the Go byte literals", () => {
  const items: [string, string][] = [
    ["ItemBacktick", "`"], ["ItemTilde", "~"], ["ItemBang", "!"], ["ItemCrosshatch", "#"],
    ["ItemAsterisk", "*"], ["ItemOpenParen", "("], ["ItemCloseParen", ")"], ["ItemHyphen", "-"],
    ["ItemUnderscore", "_"], ["ItemPlus", "+"], ["ItemEqual", "="], ["ItemTab", "\t"],
    ["ItemOpenBracket", "["], ["ItemCloseBracket", "]"], ["ItemDoublequote", '"'], ["ItemSinglequote", "'"],
    ["ItemLess", "<"], ["ItemGreater", ">"], ["ItemSpace", " "], ["ItemNewline", "\n"],
    ["ItemCarriageReturn", "\r"], ["ItemBackslash", "\\"], ["ItemSlash", "/"], ["ItemDot", "."],
    ["ItemColon", ":"], ["ItemQuestion", "?"], ["ItemAmpersand", "&"], ["ItemSemicolon", ";"],
    ["ItemPipe", "|"], ["ItemDollar", "$"], ["ItemCaret", "^"], ["ItemOpenBrace", "{"], ["ItemCloseBrace", "}"],
  ];
  assert.equal(items.length, 33);
  for (const [name, ch] of items) {
    assert.equal((lex as unknown as Record<string, number>)[name], ch.charCodeAt(0), name);
  }
});

test(`NewLexer and NextLine match Go (${vectors.lexer.length} inputs)`, () => {
  vectors.lexer.forEach((c, idx) => {
    const buf = fromHex(c.input);
    const lx = lex.NewLexer(buf);
    const lines: (string | null)[] = [];
    for (let line = lx.NextLine(); line !== null; line = lx.NextLine()) {
      lines.push(hx(line));
    }
    assert.deepEqual(lines, c.lines, `lexer#${idx} input=${c.input}`);
    assert.equal(hx(buf), c.inputAfter, `lexer#${idx} input buffer after NextLine`);
    assert.equal(lx.NextLine(), null, `lexer#${idx} end of input`);
  });
});
